// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceRequestHandler {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // Store the vtable directly.
    static let vtable: UniffiVTableCallbackInterfaceRequestHandler = UniffiVTableCallbackInterfaceRequestHandler(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterTypeRequestHandler.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface RequestHandler: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterTypeRequestHandler.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface RequestHandler: handle missing in uniffiClone")
            }
        },
        handle: { (
            uniffiHandle: UInt64,
            from: RustBuffer,
            body: RustBuffer,
            uniffiOutReturn: UnsafeMutablePointer<RustBuffer>,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> Data in
                guard let uniffiObj = try? FfiConverterTypeRequestHandler.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.handle(
                     from: try FfiConverterString.lift(from),
                     body: try FfiConverterData.lift(body)
                )
            }

            
            let writeReturn = { uniffiOutReturn.pointee = FfiConverterData.lower($0) }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
            )
        }
    )

    // Rust stores this pointer for future callback invocations, so it must live
    // for the process lifetime (not just for the init function call).
    //
    // `nonisolated(unsafe)` is needed under Swift 6 strict concurrency.
    // This is safe because the pointee is initialized once during static init
    // and never mutated by either side of the FFI.  Its fields are C function pointers.
    nonisolated(unsafe) static let vtablePtr: UnsafePointer<UniffiVTableCallbackInterfaceRequestHandler> = {
        let ptr = UnsafeMutablePointer<UniffiVTableCallbackInterfaceRequestHandler>.allocate(capacity: 1)
        ptr.initialize(to: vtable)
        return UnsafePointer(ptr)
    }()
}

private func uniffiCallbackInitRequestHandler() {
    uniffi_tethersys_ffi_fn_init_callback_vtable_requesthandler(UniffiCallbackInterfaceRequestHandler.vtablePtr)
}

