public protocol TethersysNodeProtocol: AnyObject, Sendable {
    
    func acceptFile(offer: FfiFileOffer, dest: String) async throws  -> String
    
    func checkMailbox() async throws  -> UInt32
    
    /**
     * Forward a loopback TCP port to `peer`, which serves TCP. Returns the port on
     * 127.0.0.1 to connect to; asking again for the same peer returns the same port.
     */
    func forwardTcp(peer: String) async throws  -> UInt16
    
    func id()  -> String
    
    /**
     * Invite string for a QR code or link.
     */
    func invite(ttlSecs: UInt64, uses: UInt32)  -> String
    
    func join(invite: String) async throws  -> FfiPeer
    
    func link(peer: String)  -> FfiLink?
    
    func onRequest(channel: String, handler: RequestHandler) 
    
    func peers()  -> [FfiPeer]
    
    func publish(topic: String, body: Data) async throws 
    
    func removePeer(id: String) throws  -> Bool
    
    func request(to: String, channel: String, body: Data) async throws  -> Data
    
    func send(to: String, channel: String, body: Data) async throws  -> FfiLink
    
    func sendFile(to: String, path: String) async throws  -> FfiFileOffer
    
    func shutdown() async throws 
    
    func spaceDelete(space: String, key: String) async throws 
    
    func spaceGet(space: String, key: String) async throws  -> Data?
    
    func spaceKeys(space: String) async throws  -> [String]
    
    func spaceSet(space: String, key: String, value: Data) async throws 
    
    /**
     * Close the forward to `peer`, if there is one.
     */
    func stopForward(peer: String) async throws  -> Bool
    
    func subscribe(topic: String) async throws 
    
    /**
     * Lease a tunnel and return a wg-quick config to hand to the platform VPN API.
     */
    func tunnelConfig() async throws  -> String
    
}
