        return TethersysNode(unsafeFromHandle: handle)
    }

    public static func lower(_ value: TethersysNode) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> TethersysNode {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: TethersysNode, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


