public struct FfiConverterTypeFfiEvent: FfiConverterRustBuffer {
    typealias SwiftType = FfiEvent

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiEvent {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .connected(peer: try FfiConverterString.read(from: &buf), link: try FfiConverterTypeFfiLink.read(from: &buf)
        )
        
        case 2: return .linkChanged(peer: try FfiConverterString.read(from: &buf), link: try FfiConverterTypeFfiLink.read(from: &buf), rttMs: try FfiConverterUInt64.read(from: &buf)
        )
        
        case 3: return .paired(peer: try FfiConverterString.read(from: &buf), name: try FfiConverterString.read(from: &buf)
        )
        
        case 4: return .message(from: try FfiConverterString.read(from: &buf), channel: try FfiConverterString.read(from: &buf), body: try FfiConverterData.read(from: &buf), fromMailbox: try FfiConverterBool.read(from: &buf)
        )
        
        case 5: return .fileOffered(offer: try FfiConverterTypeFfiFileOffer.read(from: &buf)
        )
        
        case 6: return .fileProgress(hash: try FfiConverterString.read(from: &buf), bytes: try FfiConverterUInt64.read(from: &buf), total: try FfiConverterUInt64.read(from: &buf)
        )
        
        case 7: return .fileDone(hash: try FfiConverterString.read(from: &buf), path: try FfiConverterString.read(from: &buf)
        )
        
        case 8: return .fileFailed(hash: try FfiConverterString.read(from: &buf), error: try FfiConverterString.read(from: &buf)
        )
        
        case 9: return .topicMessage(topic: try FfiConverterString.read(from: &buf), author: try FfiConverterString.read(from: &buf), body: try FfiConverterData.read(from: &buf)
        )
        
        case 10: return .spaceChanged(space: try FfiConverterString.read(from: &buf), key: try FfiConverterString.read(from: &buf), author: try FfiConverterString.read(from: &buf), deleted: try FfiConverterBool.read(from: &buf)
        )
        
        case 11: return .server(connected: try FfiConverterBool.read(from: &buf), detail: try FfiConverterString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FfiEvent, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .connected(peer,link):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(peer, into: &buf)
            FfiConverterTypeFfiLink.write(link, into: &buf)
            
        
        case let .linkChanged(peer,link,rttMs):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(peer, into: &buf)
            FfiConverterTypeFfiLink.write(link, into: &buf)
            FfiConverterUInt64.write(rttMs, into: &buf)
            
        
        case let .paired(peer,name):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(peer, into: &buf)
            FfiConverterString.write(name, into: &buf)
            
        
        case let .message(from,channel,body,fromMailbox):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(from, into: &buf)
            FfiConverterString.write(channel, into: &buf)
            FfiConverterData.write(body, into: &buf)
            FfiConverterBool.write(fromMailbox, into: &buf)
            
        
        case let .fileOffered(offer):
            writeInt(&buf, Int32(5))
            FfiConverterTypeFfiFileOffer.write(offer, into: &buf)
            
        
        case let .fileProgress(hash,bytes,total):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(hash, into: &buf)
            FfiConverterUInt64.write(bytes, into: &buf)
            FfiConverterUInt64.write(total, into: &buf)
            
        
        case let .fileDone(hash,path):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(hash, into: &buf)
            FfiConverterString.write(path, into: &buf)
            
        
        case let .fileFailed(hash,error):
            writeInt(&buf, Int32(8))
            FfiConverterString.write(hash, into: &buf)
            FfiConverterString.write(error, into: &buf)
            
        
        case let .topicMessage(topic,author,body):
            writeInt(&buf, Int32(9))
            FfiConverterString.write(topic, into: &buf)
            FfiConverterString.write(author, into: &buf)
            FfiConverterData.write(body, into: &buf)
            
        
        case let .spaceChanged(space,key,author,deleted):
            writeInt(&buf, Int32(10))
            FfiConverterString.write(space, into: &buf)
            FfiConverterString.write(key, into: &buf)
            FfiConverterString.write(author, into: &buf)
            FfiConverterBool.write(deleted, into: &buf)
            
        
        case let .server(connected,detail):
            writeInt(&buf, Int32(11))
            FfiConverterBool.write(connected, into: &buf)
            FfiConverterString.write(detail, into: &buf)
            
        }
    }
